-- TokANSH application database: DML playbook
--
-- Every INSERT and UPDATE the backend performs for the demo journey, in order.
-- tests/test_dml_playbook.py executes this file against a migrated database,
-- so the statements are guaranteed to match the schema.
--
-- Parameters are written :like_this. Identifiers are UUIDs generated by the
-- backend. Every :tx_* and :block_* value is whatever DRUNIX actually returned
-- for that operation: the application never invents one.
-- Money is integer paise: INR 10,000 = 1000000.

-- ## 1. Property onboarding (application workflow)
-- Meera creates TechPark One as a draft, attaches document references and submits it. Nothing touches DRUNIX.
INSERT INTO properties (id, property_name, property_type, address, city, country, illustrative_valuation_minor, issuer_id)
VALUES (:property_id, 'TechPark One', 'COMMERCIAL_OFFICE', 'Demo Address, Hinjawadi', 'Pune', 'India', 100000000000, :meera);

INSERT INTO property_documents (id, property_id, document_type, document_name, document_reference)
VALUES (:document_id, :property_id, 'TITLE_DEED', 'Title deed (synthetic)', 'demo://techpark-one/title_deed');

INSERT INTO property_valuations (id, property_id, purpose, property_value_minor, unit_value_minor, valuation_source, observed_at)
VALUES (:valuation_id, :property_id, 'COLLATERAL', 100000000000, 1000000, 'TokANSH valuation simulator', CURRENT_TIMESTAMP);

UPDATE properties SET approval_status = 'SUBMITTED', updated_at = CURRENT_TIMESTAMP
WHERE id = :property_id AND approval_status = 'DRAFT';

INSERT INTO audit_events (id, entity_type, entity_id, actor_id, operation_type, previous_state, new_state, source_system, outcome)
VALUES (:audit_submit_id, 'property', :property_id, :meera, 'PROPERTY_SUBMITTED', 'DRAFT', 'SUBMITTED', 'APPLICATION', 'SUCCESS');

-- ## 2. Review and approval (application workflow)
-- The reviewer's decision is an application record. Approval fixes the supply constraint that will be registered on DRUNIX.
UPDATE properties SET approval_status = 'UNDER_REVIEW', updated_at = CURRENT_TIMESTAMP
WHERE id = :property_id AND approval_status = 'SUBMITTED';

INSERT INTO property_reviews (id, property_id, reviewer_id, decision, approved_supply, notes)
VALUES (:review_id, :property_id, :admin, 'APPROVED', 100000, 'Synthetic evidence reviewed.');

UPDATE properties SET approval_status = 'APPROVED', verification_status = 'VERIFIED', approved_supply = 100000, updated_at = CURRENT_TIMESTAMP
WHERE id = :property_id AND approval_status = 'UNDER_REVIEW';

-- ## 3. Register the approved property on DRUNIX (ledger operation)
-- The operation row is written BEFORE submission, so an unknown outcome can be reconciled by transaction id.
INSERT INTO ledger_operations (id, operation_type, entity_type, entity_id, idempotency_key, channel, chaincode, function_name)
VALUES (:op_register, 'APPROVED_PROPERTY_REGISTRATION', 'property', :property_id, :op_register, 'mychannel', 'tokansh', 'RegisterApprovedProperty');

-- The gateway returned a transaction id: submitted, not yet committed.
UPDATE ledger_operations SET status = 'SUBMITTED', transaction_id = :tx_register, submitted_at = CURRENT_TIMESTAMP, attempt_count = attempt_count + 1, updated_at = CURRENT_TIMESTAMP
WHERE id = :op_register AND status = 'CREATED';

-- Commit status confirmed by DRUNIX. Only now may anything else change.
UPDATE ledger_operations SET status = 'COMMITTED', validation_code = 'VALID', block_number = :block_register, confirmed_at = CURRENT_TIMESTAMP, observed_at = CURRENT_TIMESTAMP, updated_at = CURRENT_TIMESTAMP
WHERE id = :op_register AND status = 'SUBMITTED';

UPDATE properties SET approved_property_ref = 'TECHPARK-ONE', drunix_registration_transaction_id = :tx_register, ledger_registered_at = CURRENT_TIMESTAMP, updated_at = CURRENT_TIMESTAMP
WHERE id = :property_id AND approval_status = 'APPROVED';

INSERT INTO asset_events (id, property_id, event_type, event_description, event_source, ledger_transaction_id, occurred_at)
VALUES (:event_register_id, :property_id, 'PROPERTY_REGISTERED', 'Approved property reference registered on DRUNIX.', 'DRUNIX_LEDGER', :tx_register, CURRENT_TIMESTAMP);

-- ## 4. Issue 100,000 ANSH (ledger operation)
INSERT INTO ledger_operations (id, operation_type, entity_type, entity_id, idempotency_key, channel, chaincode, function_name)
VALUES (:op_issue, 'ANSH_ISSUANCE', 'issuance', :issuance_id, :op_issue, 'mychannel', 'tokansh', 'IssueANSH');

INSERT INTO ansh_issuances (id, property_id, approved_property_ref, ansh_asset_id, issuer_id, approved_supply, requested_quantity, issue_price_minor, issuance_status, ledger_operation_id)
VALUES (:issuance_id, :property_id, 'TECHPARK-ONE', 'ANSH-TECHPARK-ONE', :meera, 100000, 100000, 1000000, 'SUBMITTED', :op_issue);

UPDATE ledger_operations SET status = 'SUBMITTED', transaction_id = :tx_issue, submitted_at = CURRENT_TIMESTAMP, attempt_count = attempt_count + 1, updated_at = CURRENT_TIMESTAMP
WHERE id = :op_issue AND status = 'CREATED';

UPDATE ledger_operations SET status = 'COMMITTED', validation_code = 'VALID', block_number = :block_issue, confirmed_at = CURRENT_TIMESTAMP, observed_at = CURRENT_TIMESTAMP, updated_at = CURRENT_TIMESTAMP
WHERE id = :op_issue AND status = 'SUBMITTED';

-- Supply is recognised only after the commit (Rule 3.4).
UPDATE ansh_issuances SET issuance_status = 'CONFIRMED', issued_quantity = requested_quantity, ledger_transaction_id = :tx_issue, confirmed_at = CURRENT_TIMESTAMP, updated_at = CURRENT_TIMESTAMP
WHERE id = :issuance_id AND issuance_status = 'SUBMITTED';

-- Projection of the issuer's ledger balance, traceable to the issuing transaction.
INSERT INTO ownership_positions (id, investor_id, issuance_id, owned_quantity, ledger_reference, observed_at)
VALUES (:position_meera, :meera, :issuance_id, 100000, :tx_issue, CURRENT_TIMESTAMP);

INSERT INTO asset_events (id, property_id, issuance_id, event_type, event_description, event_source, ledger_transaction_id, occurred_at)
VALUES (:event_issue_id, :property_id, :issuance_id, 'ANSH_ISSUED', '100,000 ANSH issued.', 'DRUNIX_LEDGER', :tx_issue, CURRENT_TIMESTAMP);

-- ## 5. List ANSH for sale (application workflow)
INSERT INTO marketplace_listings (id, seller_id, issuance_id, quantity, remaining_quantity, unit_price_minor, listing_status)
VALUES (:listing_id, :meera, :issuance_id, 100000, 100000, 1000000, 'ACTIVE');

-- ## 6. Purchase 500 ANSH: payment succeeds, transfer commits
-- The Idempotency-Key is stored first; a repeat of the same request returns the stored outcome instead of a second order.
INSERT INTO idempotency_records (id, idempotency_key, scope, request_hash)
VALUES (:idem_id, :order_key, 'POST /api/v1/marketplace/orders', :request_hash);

-- total_amount_minor is calculated by the backend: 500 x 1000000 (Rule 5.3).
INSERT INTO purchase_orders (id, buyer_id, seller_id, listing_id, issuance_id, quantity, unit_price_minor, total_amount_minor, idempotency_key, order_status)
VALUES (:order_id, :aarav, :meera, :listing_id, :issuance_id, 500, 1000000, 500000000, :order_key, 'PAYMENT_PENDING');

INSERT INTO payment_records (id, order_id, payment_reference, amount_minor)
VALUES (:payment_id, :order_id, :payment_ref, 500000000);

UPDATE payment_records SET payment_status = 'SUCCESS', completed_at = CURRENT_TIMESTAMP WHERE id = :payment_id;

UPDATE purchase_orders SET order_status = 'PAYMENT_SUCCEEDED', updated_at = CURRENT_TIMESTAMP
WHERE id = :order_id AND order_status = 'PAYMENT_PENDING';

INSERT INTO ledger_operations (id, operation_type, entity_type, entity_id, idempotency_key, channel, chaincode, function_name)
VALUES (:op_transfer, 'ANSH_TRANSFER', 'purchase_order', :order_id, :op_transfer, 'mychannel', 'tokansh', 'TransferANSH');

UPDATE purchase_orders SET order_status = 'TRANSFER_PENDING', transfer_operation_id = :op_transfer, updated_at = CURRENT_TIMESTAMP
WHERE id = :order_id AND order_status = 'PAYMENT_SUCCEEDED';

UPDATE ledger_operations SET status = 'SUBMITTED', transaction_id = :tx_transfer, submitted_at = CURRENT_TIMESTAMP, attempt_count = attempt_count + 1, updated_at = CURRENT_TIMESTAMP
WHERE id = :op_transfer AND status = 'CREATED';

UPDATE ledger_operations SET status = 'COMMITTED', validation_code = 'VALID', block_number = :block_transfer, confirmed_at = CURRENT_TIMESTAMP, observed_at = CURRENT_TIMESTAMP, updated_at = CURRENT_TIMESTAMP
WHERE id = :op_transfer AND status = 'SUBMITTED';

-- Projections follow the confirmed commit, in one database transaction.
UPDATE ownership_positions SET owned_quantity = owned_quantity - 500, ledger_reference = :tx_transfer, observed_at = CURRENT_TIMESTAMP, updated_at = CURRENT_TIMESTAMP
WHERE investor_id = :meera AND issuance_id = :issuance_id;

INSERT INTO ownership_positions (id, investor_id, issuance_id, owned_quantity, acquisition_cost_minor, ledger_reference, observed_at)
VALUES (:position_aarav, :aarav, :issuance_id, 500, 500000000, :tx_transfer, CURRENT_TIMESTAMP);

UPDATE marketplace_listings SET remaining_quantity = remaining_quantity - 500, listing_status = 'PARTIALLY_FILLED', updated_at = CURRENT_TIMESTAMP
WHERE id = :listing_id AND remaining_quantity >= 500;

UPDATE purchase_orders SET order_status = 'COMPLETED', updated_at = CURRENT_TIMESTAMP
WHERE id = :order_id AND order_status = 'TRANSFER_PENDING';

UPDATE idempotency_records SET response_status = 201, resource_id = :order_id, completed_at = CURRENT_TIMESTAMP WHERE id = :idem_id;

INSERT INTO asset_events (id, property_id, issuance_id, event_type, event_description, event_source, ledger_transaction_id, reference_id, occurred_at)
VALUES (:event_transfer_id, :property_id, :issuance_id, 'ANSH_TRANSFERRED', '500 ANSH transferred to the buyer.', 'DRUNIX_LEDGER', :tx_transfer, :order_id, CURRENT_TIMESTAMP);

-- ## 6a. Variant: payment fails
-- No ledger operation is created and no position changes (Rule 6.2).
INSERT INTO purchase_orders (id, buyer_id, seller_id, listing_id, issuance_id, quantity, unit_price_minor, total_amount_minor, idempotency_key, order_status)
VALUES (:order_failed_id, :aarav, :meera, :listing_id, :issuance_id, 10, 1000000, 10000000, :order_failed_key, 'PAYMENT_PENDING');

INSERT INTO payment_records (id, order_id, payment_reference, amount_minor)
VALUES (:payment_failed_id, :order_failed_id, :payment_failed_ref, 10000000);

UPDATE payment_records SET payment_status = 'FAILED', failure_reason = 'Simulated decline', completed_at = CURRENT_TIMESTAMP WHERE id = :payment_failed_id;

UPDATE purchase_orders SET order_status = 'PAYMENT_FAILED', failure_reason = 'Simulated payment declined', updated_at = CURRENT_TIMESTAMP
WHERE id = :order_failed_id AND order_status = 'PAYMENT_PENDING';

-- ## 6b. Variant: payment succeeds, ledger outcome unknown, then reconciled as failed
-- The order waits in RECONCILIATION_REQUIRED. Nothing is resubmitted blindly (ADR-011).
INSERT INTO purchase_orders (id, buyer_id, seller_id, listing_id, issuance_id, quantity, unit_price_minor, total_amount_minor, idempotency_key, order_status)
VALUES (:order_unknown_id, :aarav, :meera, :listing_id, :issuance_id, 20, 1000000, 20000000, :order_unknown_key, 'PAYMENT_SUCCEEDED');

INSERT INTO payment_records (id, order_id, payment_reference, amount_minor, payment_status, completed_at)
VALUES (:payment_unknown_id, :order_unknown_id, :payment_unknown_ref, 20000000, 'SUCCESS', CURRENT_TIMESTAMP);

INSERT INTO ledger_operations (id, operation_type, entity_type, entity_id, idempotency_key, channel, chaincode, function_name)
VALUES (:op_unknown, 'ANSH_TRANSFER', 'purchase_order', :order_unknown_id, :op_unknown, 'mychannel', 'tokansh', 'TransferANSH');

UPDATE ledger_operations SET status = 'SUBMITTED', transaction_id = :tx_unknown, submitted_at = CURRENT_TIMESTAMP, attempt_count = attempt_count + 1, updated_at = CURRENT_TIMESTAMP
WHERE id = :op_unknown AND status = 'CREATED';

-- The commit-status call timed out: the outcome is unknown, not failed.
UPDATE ledger_operations SET status = 'UNKNOWN', error_code = 'LEDGER_OUTCOME_UNKNOWN', error_message = 'Commit status timed out', observed_at = CURRENT_TIMESTAMP, updated_at = CURRENT_TIMESTAMP
WHERE id = :op_unknown AND status = 'SUBMITTED';

UPDATE purchase_orders SET order_status = 'RECONCILIATION_REQUIRED', transfer_operation_id = :op_unknown, updated_at = CURRENT_TIMESTAMP
WHERE id = :order_unknown_id;

INSERT INTO reconciliation_cases (id, ledger_operation_id, order_id, reason)
VALUES (:case_id, :op_unknown, :order_unknown_id, 'Commit status unknown after payment success');

-- Later, DRUNIX reports by transaction id that the transaction was invalidated.
UPDATE ledger_operations SET status = 'FAILED', validation_code = 'MVCC_READ_CONFLICT', error_code = 'LEDGER_COMMIT_FAILED', observed_at = CURRENT_TIMESTAMP, updated_at = CURRENT_TIMESTAMP
WHERE id = :op_unknown AND status = 'UNKNOWN';

-- The successful payment is kept; a simulated refund compensates it (Rule 6.3).
INSERT INTO payment_records (id, order_id, payment_kind, refund_of_payment_id, payment_reference, amount_minor, payment_status, completed_at)
VALUES (:refund_id, :order_unknown_id, 'REFUND', :payment_unknown_id, :refund_ref, 20000000, 'SUCCESS', CURRENT_TIMESTAMP);

UPDATE purchase_orders SET order_status = 'FAILED', failure_reason = 'Ledger transfer invalidated; payment refunded (simulated)', updated_at = CURRENT_TIMESTAMP
WHERE id = :order_unknown_id AND order_status = 'RECONCILIATION_REQUIRED';

UPDATE reconciliation_cases SET status = 'RESOLVED', resolution = 'Transaction invalidated on DRUNIX; simulated refund issued', resolved_by = :admin, resolved_at = CURRENT_TIMESTAMP
WHERE id = :case_id AND status = 'OPEN';

-- ## 7. Pledge 200 ANSH as collateral (ledger operation)
-- Collateral value = 200 x the approved collateral unit value (Rule 8.3).
INSERT INTO collateral_pledges (id, investor_id, issuance_id, quantity, collateral_unit_value_minor, collateral_value_minor, valuation_id)
VALUES (:pledge_id, :aarav, :issuance_id, 200, 1000000, 200000000, :valuation_id);

INSERT INTO ledger_operations (id, operation_type, entity_type, entity_id, idempotency_key, channel, chaincode, function_name)
VALUES (:op_pledge, 'ANSH_PLEDGE', 'collateral_pledge', :pledge_id, :op_pledge, 'mychannel', 'tokansh', 'PledgeANSH');

UPDATE collateral_pledges SET pledge_status = 'SUBMITTED', updated_at = CURRENT_TIMESTAMP WHERE id = :pledge_id AND pledge_status = 'REQUESTED';

UPDATE ledger_operations SET status = 'SUBMITTED', transaction_id = :tx_pledge, submitted_at = CURRENT_TIMESTAMP, attempt_count = attempt_count + 1, updated_at = CURRENT_TIMESTAMP
WHERE id = :op_pledge AND status = 'CREATED';

UPDATE ledger_operations SET status = 'COMMITTED', validation_code = 'VALID', block_number = :block_pledge, confirmed_at = CURRENT_TIMESTAMP, observed_at = CURRENT_TIMESTAMP, updated_at = CURRENT_TIMESTAMP
WHERE id = :op_pledge AND status = 'SUBMITTED';

UPDATE collateral_pledges SET pledge_status = 'ACTIVE', pledge_operation_id = :op_pledge, updated_at = CURRENT_TIMESTAMP
WHERE id = :pledge_id AND pledge_status = 'SUBMITTED';

-- Owned stays 500, pledged becomes 200, so available is 300.
UPDATE ownership_positions SET pledged_quantity = pledged_quantity + 200, reconciliation_status = 'RESTRICTED', ledger_reference = :tx_pledge, observed_at = CURRENT_TIMESTAMP, updated_at = CURRENT_TIMESTAMP
WHERE investor_id = :aarav AND issuance_id = :issuance_id;

-- An attempt to transfer 350 is refused by the backend and by chaincode. The refusal is audited; no ledger row is written.
-- :reject_detail is JSON such as {"code": "PLEDGED_UNITS_RESTRICTED", "requested_quantity": 350, "available_quantity": 300}.
INSERT INTO audit_events (id, entity_type, entity_id, actor_id, operation_type, source_system, outcome, detail_json)
VALUES (:audit_reject_id, 'ownership_position', :position_aarav, :aarav, 'ANSH_TRANSFER', 'APPLICATION', 'REJECTED', :reject_detail);

-- ## 8. Simulated loan against the pledge
-- LTV = 12,00,000 / 20,00,000 = 60% = 6000 bps (Rule 8.4). The threshold is configuration, not a constant.
INSERT INTO loans (id, borrower_id, lender_id, pledge_id, principal_minor, outstanding_minor, collateral_value_minor, ltv_bps, max_ltv_bps, loan_status)
VALUES (:loan_id, :aarav, :lender, :pledge_id, 120000000, 120000000, 200000000, 6000, 6000, 'UNDER_REVIEW');

INSERT INTO credit_assessments (id, loan_id, decision, assessed_ltv_bps, max_ltv_bps, assessed_by, notes)
VALUES (:assessment_id, :loan_id, 'ELIGIBLE', 6000, 6000, :lender, 'Simulated assessment.');

UPDATE loans SET loan_status = 'APPROVED', updated_at = CURRENT_TIMESTAMP WHERE id = :loan_id AND loan_status = 'UNDER_REVIEW';

UPDATE loans SET loan_status = 'ACTIVE', disbursed_at = CURRENT_TIMESTAMP, updated_at = CURRENT_TIMESTAMP WHERE id = :loan_id AND loan_status = 'APPROVED';

-- ## 9. Rental distribution using record-date holdings
INSERT INTO distributions (id, property_id, issuance_id, declared_by, period_label, total_amount_minor, record_date, distribution_date, distribution_status)
VALUES (:distribution_id, :property_id, :issuance_id, :admin, '2026-Q3 rent', 100000000, :record_date, :distribution_date, 'DECLARED');

-- Record-date ownership comes from DRUNIX (snapshot or confirmed-event reconstruction), never from today's projection (Rule 10.6).
INSERT INTO ownership_snapshots (id, issuance_id, record_date, method, ledger_reference, as_of_block_number, total_eligible_quantity, is_verified, verified_at)
VALUES (:snapshot_id, :issuance_id, :record_date, 'EVENT_RECONSTRUCTION', :tx_pledge, :block_pledge, 100000, TRUE, CURRENT_TIMESTAMP);

-- Pledged units stay eligible (Rule 10.4): eligible_quantity equals owned_quantity.
INSERT INTO ownership_snapshot_lines (id, snapshot_id, investor_id, owned_quantity, pledged_quantity, eligible_quantity)
VALUES (:line_aarav, :snapshot_id, :aarav, 500, 200, 500);

INSERT INTO ownership_snapshot_lines (id, snapshot_id, investor_id, owned_quantity, pledged_quantity, eligible_quantity)
VALUES (:line_meera, :snapshot_id, :meera, 99500, 0, 99500);

UPDATE distributions SET distribution_status = 'PROCESSING', snapshot_id = :snapshot_id, rounding_method = 'floor per holder; residual paise to the largest holder', updated_at = CURRENT_TIMESTAMP
WHERE id = :distribution_id AND distribution_status = 'DECLARED';

-- 500 / 100,000 x INR 10,00,000 = INR 5,000 (Rule 10.3).
INSERT INTO distribution_entitlements (id, distribution_id, investor_id, snapshot_id, eligible_quantity, total_eligible_quantity, entitlement_amount_minor)
VALUES (:entitlement_aarav, :distribution_id, :aarav, :snapshot_id, 500, 100000, 500000);

INSERT INTO distribution_entitlements (id, distribution_id, investor_id, snapshot_id, eligible_quantity, total_eligible_quantity, entitlement_amount_minor)
VALUES (:entitlement_meera, :distribution_id, :meera, :snapshot_id, 99500, 100000, 99500000);

-- Simulated payout.
UPDATE distribution_entitlements SET entitlement_status = 'PAID', payment_reference = 'SIM-PAYOUT-' || id, paid_at = CURRENT_TIMESTAMP
WHERE distribution_id = :distribution_id AND entitlement_status = 'CALCULATED';

UPDATE distributions SET distribution_status = 'COMPLETED', updated_at = CURRENT_TIMESTAMP
WHERE id = :distribution_id AND distribution_status = 'PROCESSING';

-- ## 10. Repay the loan and release the collateral
INSERT INTO loan_repayments (id, loan_id, amount_minor, outstanding_before_minor, outstanding_after_minor, repayment_reference, idempotency_key, repayment_status)
VALUES (:repayment_id, :loan_id, 120000000, 120000000, 0, :repayment_ref, :repayment_key, 'SUCCESS');

UPDATE loans SET outstanding_minor = outstanding_minor - 120000000, ltv_bps = 0, loan_status = 'REPAID', updated_at = CURRENT_TIMESTAMP
WHERE id = :loan_id AND outstanding_minor = 120000000;

-- Repayment alone releases nothing. The release is its own ledger operation.
UPDATE collateral_pledges SET pledge_status = 'RELEASE_PENDING', updated_at = CURRENT_TIMESTAMP WHERE id = :pledge_id AND pledge_status = 'ACTIVE';

INSERT INTO ledger_operations (id, operation_type, entity_type, entity_id, idempotency_key, channel, chaincode, function_name)
VALUES (:op_release, 'ANSH_RELEASE', 'collateral_pledge', :pledge_id, :op_release, 'mychannel', 'tokansh', 'ReleasePledge');

UPDATE ledger_operations SET status = 'SUBMITTED', transaction_id = :tx_release, submitted_at = CURRENT_TIMESTAMP, attempt_count = attempt_count + 1, updated_at = CURRENT_TIMESTAMP
WHERE id = :op_release AND status = 'CREATED';

UPDATE ledger_operations SET status = 'COMMITTED', validation_code = 'VALID', block_number = :block_release, confirmed_at = CURRENT_TIMESTAMP, observed_at = CURRENT_TIMESTAMP, updated_at = CURRENT_TIMESTAMP
WHERE id = :op_release AND status = 'SUBMITTED';

UPDATE collateral_pledges SET pledge_status = 'RELEASED', release_operation_id = :op_release, released_at = CURRENT_TIMESTAMP, updated_at = CURRENT_TIMESTAMP
WHERE id = :pledge_id AND pledge_status = 'RELEASE_PENDING';

UPDATE ownership_positions SET pledged_quantity = pledged_quantity - 200, reconciliation_status = 'ACTIVE', ledger_reference = :tx_release, observed_at = CURRENT_TIMESTAMP, updated_at = CURRENT_TIMESTAMP
WHERE investor_id = :aarav AND issuance_id = :issuance_id;

-- ## 11. Read queries behind the main screens
-- ANSH portfolio with owned, pledged and available shown separately.
SELECT p.property_name, o.owned_quantity, o.pledged_quantity, o.owned_quantity - o.pledged_quantity AS available_quantity, o.acquisition_cost_minor, o.ledger_reference, o.observed_at
FROM ownership_positions o JOIN ansh_issuances i ON i.id = o.issuance_id JOIN properties p ON p.id = i.property_id
WHERE o.investor_id = :aarav;

-- REIT holdings are read separately and never joined to ANSH tables.
SELECT reit_name, quantity, purchase_value_minor, illustrative_market_value_minor, is_simulated FROM reit_holdings WHERE investor_id = :aarav;

-- Total ownership must equal confirmed issued supply (Rule 4.3).
SELECT i.issued_quantity, SUM(o.owned_quantity) AS total_owned FROM ansh_issuances i JOIN ownership_positions o ON o.issuance_id = i.id
WHERE i.id = :issuance_id GROUP BY i.issued_quantity;

-- Entitlements must sum to the declared amount (Rule 10.5).
SELECT d.total_amount_minor, SUM(e.entitlement_amount_minor) AS total_entitled FROM distributions d JOIN distribution_entitlements e ON e.distribution_id = d.id
WHERE d.id = :distribution_id GROUP BY d.total_amount_minor;

-- Lifecycle timeline, with the source of every event visible.
SELECT occurred_at, event_type, event_source, is_simulated, ledger_transaction_id FROM asset_events WHERE property_id = :property_id ORDER BY occurred_at;

-- Operations that still need a human or a status check.
SELECT id, operation_type, status, transaction_id, error_code FROM ledger_operations WHERE status IN ('UNKNOWN', 'RECONCILIATION_REQUIRED');
